// Fits the standard Arrakis board (61 spaces) to the map: spice fields where the map shows spice, terrain zones after
// the map, plant-like bonuses after the terrain (scripts/arrakisGeography.ts has the rules).
// Why: the board must match the drawn planet (assets/themes/dune/source/arrakis-globe.png). The bonus layout itself –
// which space carries steel, titanium, cards, double bonuses, the Tharsis totals – stays as designed; a bonus only moves
// with its spice field when the spice field moves. Never edit the generated files by hand – run, after
// scripts/measure-arrakis-globe.py:
//   npx tsx scripts/make-arrakis-61.ts && npx tsx scripts/make-arrakis-91.ts
// Writes src/server/boards/arrakis61Spaces.ts and src/common/dune/arrakisTerrain.ts.
import * as fs from 'fs';
import * as path from 'path';
import {SpaceBonus} from '../src/common/boards/SpaceBonus';
import {SpaceName} from '../src/common/boards/SpaceName';
import {ArrakisZone} from '../src/common/dune/arrakisTerrain';
import {WORM_START_SPACES} from '../src/common/dune/wormStartSpaces';
import {ARRAKIS_61_ROWS} from '../src/server/boards/arrakis61Spaces';
import {ArrakisSpaceDefinition} from '../src/server/boards/arrakisRows';
import {bonusForZone, chooseSpiceFields, landZone, loadMeasures, planetDistance} from './arrakisGeography';

const ROOT = path.join(__dirname, '..');
// The polar sink of the map (ice in the middle): the worm never enters it (Jens' worm line, 19 Oct 2026)
const BEHIND_WORM_BORDER = ['33', '34', '41', '42', '49'];
const SPICE_FIELDS = 12;

const measures = loadMeasures('61');
const spaces = new Map<string, ArrakisSpaceDefinition>();
ARRAKIS_61_ROWS.flat().forEach((space, index) => spaces.set(String(index + 3).padStart(2, '0'), {kind: space.kind, bonus: [...space.bonus]}));
const ids = [...spaces.keys()];
const arrakeen: string = SpaceName.ARRAKEEN;

// Spice fields after the map; a spice field that moves takes its bonus along to the nearest new one
const previous = new Set(ids.filter((id) => spaces.get(id)!.kind === 'ocean'));
const excluded = new Set([arrakeen, ...BEHIND_WORM_BORDER, ...WORM_START_SPACES, ...ids.filter((id) => spaces.get(id)!.kind === 'volcanic')]);
const oceans = chooseSpiceFields(measures, SPICE_FIELDS, excluded, previous);
const dropped = [...previous].filter((id) => !oceans.has(id));
const added = [...oceans].filter((id) => !previous.has(id));
for (const id of added) {
  const from = dropped.reduce((best, other) => planetDistance(measures[other], measures[id]) < planetDistance(measures[best], measures[id]) ? other : best);
  dropped.splice(dropped.indexOf(from), 1);
  const bonus = spaces.get(id)!.bonus;
  spaces.set(id, {kind: 'ocean', bonus: spaces.get(from)!.bonus});
  spaces.set(from, {kind: 'land', bonus});
  console.log(`spice field ${from} -> ${id}`);
}

const zones: Record<string, ArrakisZone> = {};
for (const id of ids) {
  const space = spaces.get(id)!;
  zones[id] = space.kind === 'ocean' ? 'spicefield' : id === arrakeen ? 'city' : landZone(measures[id]);
  if (space.kind === 'volcanic' && zones[id] !== 'rock') {
    console.warn(`volcanic space ${id} is not on rock (${zones[id]})`);
  }
  space.bonus = bonusForZone(space.bonus, zones[id]);
}

// --- Output ---
const BONUS_NAME: Partial<Record<SpaceBonus, string>> = {
  [SpaceBonus.PLANT]: 'PLANT', [SpaceBonus.STEEL]: 'STEEL', [SpaceBonus.TITANIUM]: 'TITANIUM', [SpaceBonus.DRAW_CARD]: 'DRAW_CARD',
  [SpaceBonus.HEAT]: 'HEAT', [SpaceBonus.ENERGY]: 'ENERGY',
};
const rows: Array<Array<string>> = [];
let index = 0;
for (const row of ARRAKIS_61_ROWS) {
  rows.push(row.map(() => {
    const space = spaces.get(ids[index++])!;
    return `{kind: '${space.kind}', bonus: [${space.bonus.map((b) => 'SpaceBonus.' + BONUS_NAME[b]).join(', ')}]}`;
  }));
}
fs.writeFileSync(path.join(ROOT, 'src/server/boards/arrakis61Spaces.ts'), `// GENERATED by scripts/make-arrakis-61.ts – do not edit by hand.
// The standard Arrakis board row by row (5 to 9 spaces, ids 03 to 63 in reading order), read by Arrakis61Board.ts:
// the designed bonus layout with spice fields and plant-like bonuses fitted to the map.
import {SpaceBonus} from '../../common/boards/SpaceBonus';
import {ArrakisSpaceDefinition} from './arrakisRows';

export const ARRAKIS_61_ROWS: ReadonlyArray<ReadonlyArray<ArrakisSpaceDefinition>> = [
${rows.map((row) => '  [' + row.join(', ') + '],').join('\n')}
];
`);

const quote = (value: string) => `'${value}'`;
fs.writeFileSync(path.join(ROOT, 'src/common/dune/arrakisTerrain.ts'), `// GENERATED by scripts/make-arrakis-61.ts from the map – do not edit by hand.
// Terrain of every space of the standard Arrakis board (Arrakis61Board.ts) and the spaces behind the worm border
// around the polar sink.

export type ArrakisZone = 'spicefield' | 'basin' | 'rock' | 'erg' | 'city' | 'ice';

export const ARRAKIS_ZONES: Readonly<Record<string, ArrakisZone>> = {
${ids.map((id) => `  ${quote(id)}: ${quote(zones[id])},`).join('\n')}
};

/** Spaces behind the worm border (polar sink): the worm never enters them */
export const BEHIND_WORM_BORDER: ReadonlyArray<string> = [${BEHIND_WORM_BORDER.map(quote).join(', ')}];
`);
const count = (zone: ArrakisZone) => ids.filter((id) => zones[id] === zone).join(' ');
console.log('spice', count('spicefield'), '| ice', count('ice'), '| basin', count('basin'), '| rock', count('rock'));
